function UIBattleEndContinuousFightConfirmDialog:InitComponent()
    local continueType = teamComponent:GetContinueType()
    local totalTimes = continueType == Constants.ContinueBattleType.NoLimit and "∞" or teamComponent:GetContinueNum()
    self.Txt_DescFightTimes.text = localize("进行了_num1_/_num2_场", {_num1_ = teamComponent:GetCurContinueNum(), _num2_ = totalTimes})
    SetButtonAction(self.Btn_Abort, function()
        teamComponent:SetCurContinueState(false)
        self:StopInputLimitTimer()
        UIModule.BackDialog()
    end)
end


--- 倒计时
---@param callBackCD any
---@param callBackFinish any
---@param timeLimit any
function UIBattleEndContinuousFightConfirmDialog:StartInputLimitTimer(callBackCD, callBackFinish, timeLimit)
    self.coInputLimitTimer = cs_coroutine.start(function()
        if callBackCD then
            callBackCD(timeLimit)
        end
        local timer = 0
        while timer < timeLimit do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            timer = timer + 1
            if callBackCD then
                callBackCD(timeLimit - timer)
            end
        end
        if callBackFinish then
            callBackFinish()
        end
        self.coInputLimitTimer = nil
    end)
end

function UIBattleEndContinuousFightConfirmDialog:StopInputLimitTimer()
    if self.coInputLimitTimer then
        cs_coroutine.stop(self.coInputLimitTimer)
        self.coInputLimitTimer = nil
    end
end

function UIBattleEndContinuousFightConfirmDialog:UpdateTimerText(remainTime)
    self.Txt_CountDown.text = tostring(remainTime)
end

function UIBattleEndContinuousFightConfirmDialog:NextBattle()
    UIModule.BackDialog()
end


